<?php $case=$case??[]; ?>
<article class="card"><span class="eyebrow">تجربه عملی · نسخه <?= $this->h($experience['version_no']) ?></span><h1><?= $this->h($experience['title']) ?></h1><?php if($case): ?><p class="prose"><?= nl2br($this->h($case['summary'])) ?></p><div class="case-overview"><span class="tag">نتیجه: <?= $this->h(['success'=>'موفق','failure'=>'ناموفق','mixed'=>'ترکیبی','unknown'=>'نامشخص'][$case['outcome']]) ?></span><?php foreach(['activity_area','period','setting'] as $key): if(!empty($case[$key])): ?><span class="tag"><?= $this->h($case[$key]) ?></span><?php endif; endforeach; ?></div><?php endif; ?><p>صاحب تجربه: <a class="textlink" href="<?= $this->h($this->url('/mentor/profile?id='.$experience['mentor_id'].'&experience_id='.$experience['id'])) ?>"><?= $this->h($experience['display_name']) ?></a></p><?php if(!$case): ?><p class="prose"><?= nl2br($this->h($experience['body'])) ?></p><?php endif; ?></article>
<?php if($case): ?><section class="card section"><h2>این تجربه برای چه کسانی مفید است؟</h2><?php foreach(['problem_statement'=>'مسئله مخاطب','target_audience'=>'گروه هدف','scale'=>'مقیاس','applicability'=>'شرایط کاربرد','constraints'=>'محدودیت‌های استفاده'] as $key=>$label): if(!empty($case[$key])): ?><h3><?= $label ?></h3><p class="prose"><?= nl2br($this->h($case[$key])) ?></p><?php endif; endforeach; ?></section><article class="card section"><?php foreach(\Morshed\Product\ExperienceCases::NARRATIVE as $key=>$label): if(!empty($case[$key])): ?><section class="case-narrative"><h2><?= $label ?></h2><?php if($key==='actions'): ?><ol class="case-steps"><?php foreach(preg_split('/\R/u',$case[$key]) as $step): if(trim($step)!==''): ?><li><?= $this->h($step) ?></li><?php endif; endforeach; ?></ol><?php else: ?><p class="prose"><?= nl2br($this->h($case[$key])) ?></p><?php endif; ?></section><?php endif; endforeach; ?></article><?php endif; ?>
<section class="card section"><h2>با صاحب این تجربه گفت‌وگو کن</h2><p><?= $this->h($experience['display_name']) ?><?php if(!empty($case['role'])): ?> · <?= $this->h($case['role']) ?><?php endif; ?></p><?php if(!empty($case['consultation_topics'])): ?><p class="prose"><?= nl2br($this->h($case['consultation_topics'])) ?></p><?php endif; ?><a class="primary" href="<?= $this->h($this->url('/mentor/profile?id='.$experience['mentor_id'].'&experience_id='.$experience['id'])) ?>">شناخت مرشد و درخواست گفت‌وگو دربارهٔ این تجربه</a><p class="muted">مشاوره رایگان است؛ رزرو عمومی فعلاً بسته است.</p></section>
<?php if($assets): ?><section class="card section"><h2>مستندات منتشرشده همین نسخه</h2><?php foreach($assets as $asset): ?><p><a class="secondary" href="<?= $this->h($this->url('/content/asset?id='.$asset['id'])) ?>"><?= $this->h($asset['display_name']) ?></a></p><?php if(in_array($asset['media_type'],['image/png','image/jpeg'],true)): ?><img class="evidence-image" loading="lazy" src="<?= $this->h($this->url('/content/asset?id='.$asset['id'])) ?>" alt="<?= $this->h($asset['display_name']) ?>"><?php endif; endforeach; ?></section><?php endif; ?>
<?php if(!empty($related)): ?><section class="section"><h2>تجربه‌های مرتبط</h2><div class="grid2"><?php foreach($related as $item): ?><article class="card"><h3><?= $this->h($item['title']) ?></h3><p><?= $this->h($item['display_name']) ?></p><a class="textlink" href="<?= $this->h($this->url('/experience?id='.$item['id'])) ?>">مشاهده تجربه</a></article><?php endforeach; ?></div></section><?php endif; ?>
